def reshape(self, data_shapes, label_shapes):
        """Reshape executors.

        Parameters
        ----------
        data_shapes : list
        label_shapes : list
        """
        if data_shapes == self.data_shapes and label_shapes == self.label_shapes:
            return
        if self._default_execs is None:
            self._default_execs = [i for i in self.execs]
        self.bind_exec(data_shapes, label_shapes, reshape=True)
        for name, shape in data_shapes:
            if name in self.data_names:
                self.data_shapes[name] = shape
        for name, shape in label_shapes:
            if name in self.label_names:
                self.label_shapes[name] = shape
        for name, executor in self.exec_group.items():
